  if(breeze&&caps.features.sentence_splitting)payload.split_sentences=!$('noSentenceSplitting').checked;
  if(cloningSupported())payload.clone_mode=document.querySelector('input[name=clone]:checked').value;
  const direction=$('instructions').disabled?'':$('instructions').value.trim();
  if(breeze&&design){
    const description=$('voiceDescription').value.trim();
    if(!description)throw Error('Bitte die gewünschte Stimme beschreiben.');
    payload.instructions=[description,direction].filter(Boolean).join(' ');
  }else if(direction)payload.instructions=direction;
  if(design&&!payload.instructions)throw Error(breeze?'Bitte die gewünschte Stimme beschreiben.':'Describe the voice you want.');
